window.docContents[43].resolve({"/References/#Type-Systems--References___-Typing-Mutable-References--Definitions--Typing-_LPAR_Preview_RPAR_":{"contents":"Informally, the typing rules for allocation, dereferencing, and\nassignment look roughly like this:\n\n      Γ ⊢ t₁ ⦂ τ₁\n---------------------  (ref)\n  Γ ⊢ ref t₁ ⦂ Ref τ₁\n\n      Γ ⊢ t₁ ⦂ Ref τ₁\n---------------------  (deref)\n     Γ ⊢ !t₁ ⦂ τ₁\n\n      Γ ⊢ t₁ ⦂ Ref τ₂\n      Γ ⊢ t₂ ⦂ τ₂\n---------------------  (assign)\nΓ ⊢ t₁ := t₂ ⦂ Unit\n\n\nThe rule for locations will require a bit more machinery, and this\nwill motivate some changes to the other rules; we'll come back to\nthis later.\n\n","context":"Type Systems\u0009References: Typing Mutable References\u0009Definitions","header":"9.1.4. Typing (Preview)","id":"/References/#Type-Systems--References___-Typing-Mutable-References--Definitions--Typing-_LPAR_Preview_RPAR_"}});